<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Falling Sand</title>
<style>
*{margin:0;padding:0;box-sizing:border-box}
body{
  background:#0d0d1a;color:#ccc;
  font-family:system-ui,-apple-system,sans-serif;
  display:flex;flex-direction:column;align-items:center;justify-content:center;
  min-height:100vh;gap:14px;user-select:none;
}
h1{font-size:1.1rem;color:#666;letter-spacing:3px;text-transform:uppercase}
#controls{display:flex;gap:8px;flex-wrap:wrap;justify-content:center}
button{
  padding:8px 18px;border:2px solid transparent;border-radius:8px;
  cursor:pointer;font-size:13px;font-weight:700;letter-spacing:.5px;
  transition:transform .1s,border-color .15s,box-shadow .15s;
  color:#fff;text-shadow:0 1px 2px rgba(0,0,0,.5);
}
button:hover{transform:scale(1.06)}
button.active{border-color:#fff;box-shadow:0 0 12px rgba(255,255,255,.25)}
#mat-sand{background:#b8962a}
#mat-water{background:#2563a8}
#mat-wall{background:#4a4a5a}
#mat-acid{background:#1a9a10}
#mat-empty{background:#2a2a35;color:#aaa}
#clear{background:#7a1a1a}
#sand{
  border:2px solid #2a2a3a;border-radius:4px;
  cursor:crosshair;image-rendering:pixelated;image-rendering:crisp-edges;
  display:block;
}
</style>
</head>
<body>
<h1>Falling Sand</h1>
<div id="controls">
  <button id="mat-sand" class="active">Sand</button>
  <button id="mat-water">Water</button>
  <button id="mat-wall">Wall</button>
  <button id="mat-acid">Acid</button>
  <button id="mat-empty">Eraser</button>
  <button id="clear">Clear</button>
</div>
<canvas id="sand"></canvas>
<script>
(function(){
"use strict";

const W=100,H=100,CELL=5,CW=W*CELL,CH=H*CELL;
const canvas=document.getElementById('sand');
canvas.width=CW;canvas.height=CH;
canvas.style.width=CW+'px';canvas.style.height=CH+'px';
const ctx=canvas.getContext('2d');
const imgData=ctx.createImageData(CW,CH);
const pixels=imgData.data;

// 0=empty 1=sand 2=water 3=wall 4=acid
const grid=new Uint8Array(W*H);
const moved=new Uint8Array(W*H);
const shade=new Int8Array(W*H);

const MAT_NAMES=['empty','sand','water','wall','acid'];
const MAT_ID={empty:0,sand:1,water:2,wall:3,acid:4};

const BR=[18,210,50,85,35];
const BG=[18,185,115,85,215];
const BB=[30,55,195,100,15];

let selectedMat=1;

// UI
const matBtns={'mat-sand':1,'mat-water':2,'mat-wall':3,'mat-acid':4,'mat-empty':0};
for(const[id,mat]of Object.entries(matBtns)){
  document.getElementById(id).addEventListener('click',function(){
    selectedMat=mat;
    for(const bid of Object.keys(matBtns))
      document.getElementById(bid).classList.toggle('active',bid===id);
  });
}
document.getElementById('clear').addEventListener('click',function(){sim.clear()});

// Painting
let painting=false,lastGX=-1,lastGY=-1;

function c2g(e){
  const r=canvas.getBoundingClientRect();
  return[Math.floor((e.clientX-r.left)/r.width*W),Math.floor((e.clientY-r.top)/r.height*H)];
}

function brush(gx,gy){
  const rad=2;
  for(let dy=-rad;dy<=rad;dy++)for(let dx=-rad;dx<=rad;dx++){
    if(dx*dx+dy*dy>rad*rad+1)continue;
    const nx=gx+dx,ny=gy+dy;
    if(nx>=0&&nx<W&&ny>=0&&ny<H){
      const idx=ny*W+nx;
      grid[idx]=selectedMat;
      shade[idx]=(Math.random()*30-15)|0;
    }
  }
}

function bline(x0,y0,x1,y1){
  const dx=Math.abs(x1-x0),dy=Math.abs(y1-y0);
  const sx=x0<x1?1:-1,sy=y0<y1?1:-1;
  let err=dx-dy,x=x0,y=y0;
  for(let s=0;s<2000;s++){
    brush(x,y);
    if(x===x1&&y===y1)break;
    const e2=err<<1;
    if(e2>-dy){err-=dy;x+=sx}
    if(e2<dx){err+=dx;y+=sy}
  }
}

function pDown(e){
  e.preventDefault();painting=true;
  const p=e.touches?e.touches[0]:e;
  const[gx,gy]=c2g(p);lastGX=gx;lastGY=gy;brush(gx,gy);
}
function pMove(e){
  if(!painting)return;e.preventDefault();
  const p=e.touches?e.touches[0]:e;
  const[gx,gy]=c2g(p);
  if(gx!==lastGX||gy!==lastGY){bline(lastGX,lastGY,gx,gy);lastGX=gx;lastGY=gy}
}
function pUp(){painting=false}

canvas.addEventListener('mousedown',pDown);
canvas.addEventListener('mousemove',pMove);
window.addEventListener('mouseup',pUp);
canvas.addEventListener('touchstart',pDown,{passive:false});
canvas.addEventListener('touchmove',pMove,{passive:false});
canvas.addEventListener('touchend',pUp);

// Simulation
function moveSand(x,y,i){
  const by=y+1;
  if(by>=H)return;
  const bi=by*W+x,bc=grid[bi];
  if(bc===0){
    grid[bi]=1;grid[i]=0;shade[bi]=shade[i];moved[bi]=1;return;
  }
  if((bc===2||bc===4)&&!moved[bi]){
    grid[bi]=1;grid[i]=bc;
    const t=shade[bi];shade[bi]=shade[i];shade[i]=t;
    moved[bi]=1;moved[i]=1;return;
  }
  const d=Math.random()<.5?-1:1;
  for(let dir=d;;dir=-dir){
    const nx=x+dir;
    if(nx>=0&&nx<W){
      const di=by*W+nx,dc=grid[di];
      if(dc===0){
        grid[di]=1;grid[i]=0;shade[di]=shade[i];moved[di]=1;return;
      }
      if((dc===2||dc===4)&&!moved[di]){
        grid[di]=1;grid[i]=dc;
        const t=shade[di];shade[di]=shade[i];shade[i]=t;
        moved[di]=1;moved[i]=1;return;
      }
    }
    if(dir===-d)break;
  }
}

function moveWater(x,y,i){
  const by=y+1;
  if(by<H){
    const bi=by*W+x;
    if(grid[bi]===0){
      grid[bi]=2;grid[i]=0;shade[bi]=shade[i];moved[bi]=1;return;
    }
    const d=Math.random()<.5?-1:1;
    for(let dir=d;;dir=-dir){
      const nx=x+dir;
      if(nx>=0&&nx<W){
        const di=by*W+nx;
        if(grid[di]===0){
          grid[di]=2;grid[i]=0;shade[di]=shade[i];moved[di]=1;return;
        }
      }
      if(dir===-d)break;
    }
  }
  const d=Math.random()<.5?-1:1;
  for(let dir=d;;dir=-dir){
    const nx=x+dir;
    if(nx>=0&&nx<W){
      const si=y*W+nx;
      if(grid[si]===0){
        grid[si]=2;grid[i]=0;shade[si]=shade[i];moved[si]=1;return;
      }
    }
    if(dir===-d)break;
  }
}

function moveAcid(x,y,i){
  const by=y+1;
  const d=Math.random()<.5?-1:1;

  if(by<H){
    const bi=by*W+x,bc=grid[bi];
    if(bc===1||bc===3){
      grid[bi]=0;
      if(Math.random()<(bc===1?.5:.3))grid[i]=0;
      moved[i]=1;return;
    }
  }

  for(let dir=d;;dir=-dir){
    const nx=x+dir;
    if(nx>=0&&nx<W){
      const si=y*W+nx,sc=grid[si];
      if(sc===1||sc===3){
        grid[si]=0;
        if(Math.random()<(sc===1?.5:.3))grid[i]=0;
        moved[i]=1;return;
      }
    }
    if(dir===-d)break;
  }

  if(by<H){
    const bi=by*W+x;
    if(grid[bi]===0){
      grid[bi]=4;grid[i]=0;shade[bi]=shade[i];moved[bi]=1;return;
    }
    for(let dir=d;;dir=-dir){
      const nx=x+dir;
      if(nx>=0&&nx<W){
        const di=by*W+nx;
        if(grid[di]===0){
          grid[di]=4;grid[i]=0;shade[di]=shade[i];moved[di]=1;return;
        }
      }
      if(dir===-d)break;
    }
  }

  for(let dir=d;;dir=-dir){
    const nx=x+dir;
    if(nx>=0&&nx<W){
      const si=y*W+nx;
      if(grid[si]===0){
        grid[si]=4;grid[i]=0;shade[si]=shade[i];moved[si]=1;return;
      }
    }
    if(dir===-d)break;
  }
}

function tick(){
  moved.fill(0);
  for(let y=H-1;y>=0;y--){
    const ltr=Math.random()<.5;
    for(let j=0;j<W;j++){
      const x=ltr?j:(W-1-j);
      const i=y*W+x;
      if(moved[i])continue;
      const c=grid[i];
      if(c===0||c===3)continue;
      if(c===1)moveSand(x,y,i);
      else if(c===2)moveWater(x,y,i);
      else if(c===4)moveAcid(x,y,i);
    }
  }
}

// Rendering
function render(){
  for(let y=0;y<H;y++){
    const py=y*CELL;
    for(let x=0;x<W;x++){
      const c=grid[y*W+x];
      const s=shade[y*W+x];
      const r=BR[c]+s,g=BG[c]+s,b=BB[c]+s;
      const px=x*CELL;
      for(let dy=0;dy<CELL;dy++){
        let pi=((py+dy)*CW+px)*4;
        for(let dx=0;dx<CELL;dx++){
          pixels[pi]=r;pixels[pi+1]=g;pixels[pi+2]=b;pixels[pi+3]=255;
          pi+=4;
        }
      }
    }
  }
  ctx.putImageData(imgData,0,0);
}

// Animation
function loop(){
  tick();
  render();
  requestAnimationFrame(loop);
}

// API
window.sim={
  w:W,h:H,
  tick:function(n){for(let i=0;i<n;i++)tick()},
  get:function(x,y){
    if(x<0||x>=W||y<0||y>=H)return'empty';
    return MAT_NAMES[grid[y*W+x]];
  },
  set:function(x,y,material){
    if(x<0||x>=W||y<0||y>=H)return;
    const id=MAT_ID[material];
    if(id===undefined)return;
    const idx=y*W+x;
    grid[idx]=id;
    shade[idx]=(Math.random()*30-15)|0;
  },
  clear:function(){grid.fill(0);shade.fill(0)}
};

render();
requestAnimationFrame(loop);
})();
</script>
</body>
</html>
